/* startup.S calls initialise_monitor_handles to open the standard file handles
   over a debugger connection. The GNU toolchain provides it in libgloss, which
   --specs=rdimon.specs pulls in, so this file is linked only for the LLVM
   toolchain: picolibc has no equivalent, and neither does the toolchain's own
   semihosting library, so without it the sample does not link at all.

   The definition is weak, so a real one always wins if something provides it.
   The sample writes nothing to the standard handles, so doing nothing here
   costs it no output.  */

    .text
    .balign 4

    .weak initialise_monitor_handles
    .type initialise_monitor_handles, %function
initialise_monitor_handles:
    ret
    .size initialise_monitor_handles, . - initialise_monitor_handles

    .end
